"use client";
import { jsx } from "react/jsx-runtime";
//#region src/media/fallback.tsx
const MEDIA_HELP_URL = "https://videojs.org/help";
/** Default `fallback` for Medias that render a `<video>`. */
const videoFallback = /* @__PURE__ */ jsx("a", {
	href: MEDIA_HELP_URL,
	children: "Video player not working?"
});
/** Default `fallback` for Medias that render an `<audio>`. */
const audioFallback = /* @__PURE__ */ jsx("a", {
	href: MEDIA_HELP_URL,
	children: "Audio player not working?"
});
//#endregion
export { audioFallback, videoFallback };
